import random
from collections import Counter

def task_func(strings: list) -> dict:
    """
    Count occurrences of the literal substring "pattern" across a list of strings.

    Non-string items are ignored. Matching is case-sensitive and counts
    overlapping occurrences.
    """
    target_pattern = "pattern"
    counts = Counter()

    def _count_overlapping(text: str, pattern: str) -> int:
        if pattern == "":
            return len(text) + 1
        total = 0
        start = 0
        while True:
            idx = text.find(pattern, start)
            if idx == -1:
                break
            total += 1
            start = idx + 1
        return total

    for item in strings:
        if isinstance(item, str):
            counts[target_pattern] += _count_overlapping(item, target_pattern)

    if target_pattern not in counts:
        counts[target_pattern] = 0

    return dict(counts)
